from collections import deque

def find_friends_of_friends(graph, user, max_depth=2):
    """BFS 发现潜在好友（类似 LinkedIn 推荐）"""
    visited = {user}
    queue = deque([(user, 0)])
    recommendations = []

    while queue:
        current, depth = queue.popleft()
        if depth >= max_depth:
            break
        for friend in graph.get(current, []):
            if friend not in visited:
                visited.add(friend)
                queue.append((friend, depth + 1))
                # 非直接好友才推荐
                if depth >= 1:
                    recommendations.append(
                        (friend, depth + 1)
                    )
    return recommendations

