import java.util.*;

public class ServerSelection {
    /**
     * 0-1 背包：有限预算下选择最优服务器组合
     * budget: 月预算（元）
     * costs: 每种配置的月费用
     * scores: 每种配置的性能评分
     */
    public static int maxPerformance(
            int budget, int[] costs, int[] scores) {
        int n = costs.length;
        int[] dp = new int[budget + 1];

        for (int i = 0; i < n; i++) {
            // 逆序遍历保证每个配置只选一次
            for (int j = budget; j >= costs[i]; j--) {
                dp[j] = Math.max(
                    dp[j], dp[j - costs[i]] + scores[i]
                );
            }
        }
        return dp[budget];
    }

    public static void main(String[] args) {
        // 月预算 1000 元
        int budget = 1000;
        // 配置: 2C4G/4C8G/8C16G/16C32G
        int[] costs = {200, 400, 700, 1000};
        int[] scores = {30, 55, 85, 100};

        int best = maxPerformance(budget, costs, scores);
        System.out.println("最优性能评分: " + best);
    }
}
